INSERT INTO purpose VALUES('theory-discrete-morse','abelian::Abelian','struct','Reads a complex''s composites as integer chains, so the equivalence of any complex gives its linear shadow and the reduct''s Morse boundary is checked against it.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','abelian::Chain','struct','Holds an integer chain: each cell with its coefficient, in cell order, with no coefficient zero.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','collapse::Class','enum','Names what a scheme makes of a cell: critical, or paired with its partner one dimension up or one dimension down.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','collapse::Collapse','struct','Holds what the check of a scheme gives: the critical cells among those given, the faults, and the pairs the walk reaches.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','collapse::Faults','struct','Holds the count of each fault a check finds: partners that do not name their cell back, partners outside the complex, pairs that the complex''s pairing condition refuses, and edges that close a cycle of the gradient.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','collapse::Scheme','trait','States the class of each cell of a complex, so the check reads a matching that a caller gives by a rule.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','collapse::collapse','function','Checks a scheme as an acyclic matching on the cells a caller gives and follows the gradient past them up to a budget, so the critical cells and the faults are read.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','complex::Complex','trait','States the faces of a cell one dimension down with their incidence, whether a cell lies in the complex, and whether a face can pair with a cell, so a check and a matching read a complex the caller holds.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','complex::Incidence','struct','Names the integer with which a face enters the boundary of a cell, so a matching pairs only along a unit.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','complex::Invertibility','enum','Names whether a pair is allowed: an incidence of one or minus one, or the complex''s own pairing condition.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','complex::Standing','enum','Names whether a cell lies in a complex, so a partner outside it is counted.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','equivalence::Bound','struct','Holds an equivalence read on the complex it was built on, with the collapse, the witnesses and the inclusion built once, so it is a reduction that composes in sequence.','collapse oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','equivalence::Composites','trait','States a complex''s own composites and witnesses, with the definition of a redundant cell by its partner, substitution, the carrying, composition and whiskering of witnesses, conjugation and the replay of a witness, so the equivalence is built on paths or whiskered terms and not on chains alone.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','equivalence::Definition','struct','Holds the definition of a redundant cell by its partner: the composite in the cell''s place and the witness from the cell to it.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','equivalence::Equivalence','struct','Holds the equivalence of a complex with its reduct along an acyclic matching: the critical cells and the removals in gradient order, which a caller keeps, reads on its complex as a reduction, and replays.','collapse oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','equivalence::EquivalenceOf','type_alias','Names the equivalence that the composites of a scheme give, so the build''s signature reads in the scheme''s own types.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','equivalence::Images','struct','Holds the images that a substitution or a conjugation reads, each removed cell with what takes its place.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','equivalence::Removal','struct','Holds one removal of a matching: the redundant cell, its partner and the definition of the cell by the partner.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','equivalence::equivalence','function','Builds the equivalence of a complex with its reduct along the matching a scheme gives, the matching checked first and the removals put in gradient order.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','gradient::Place','struct','Names a cell by its place in the list a walk or a matching reads, so a node of the gradient graph is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','greedy::greedy','function','Builds an acyclic matching on a finite list of cells, each pair kept only when no gradient path runs back from its upper cell to its lower one.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','matching::Matched','struct','Holds a matching with the complex it pairs, so the check reads the matching as a scheme over the complex''s own faces, pairing condition and composites.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','matching::Matching','struct','Holds the class of each cell of a list, as the greedy matching pairs it or a caller states it pair by pair, so its critical cells and its pairs are read.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','reduct::Reduct','struct','Holds the reduct of a complex along an acyclic matching: the critical cells by rank and then by place, the Morse boundary of each and the walk of its gradient.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-discrete-morse','reduct::reduct','function','Builds the reduct of a complex along an acyclic matching, each boundary summed once along the gradient paths up to a budget, so the critical cells and their boundaries are read.','collapse','fits','sound',NULL);
